CREATE MATERIALIZED VIEW gold.session_state_mv TO gold.session_state (`session_month` Date, `video_session_id` FixedString(64), `user_id` AggregateFunction(any, FixedString(64)), `content_id` AggregateFunction(any, Int64), `platform` AggregateFunction(any, LowCardinality(String)), `video_resolution` AggregateFunction(any, LowCardinality(String)), `country` AggregateFunction(any, LowCardinality(String)), `app_version` AggregateFunction(any, LowCardinality(String)), `audio_languages` AggregateFunction(groupUniqArray, String), `subtitle_languages` AggregateFunction(groupUniqArray, String), `player_version` AggregateFunction(any, LowCardinality(String)), `session_start_epoch` AggregateFunction(any, DateTime64(3, 'UTC')), `title` AggregateFunction(any, String), `video_type` AggregateFunction(any, String), `category` AggregateFunction(any, String), `show_name` AggregateFunction(any, String), `latest_event_type` AggregateFunction(argMax, String, DateTime64(3, 'UTC')), `latest_event` AggregateFunction(argMax, String, DateTime64(3, 'UTC')), `last_event_ts` SimpleAggregateFunction(max, DateTime64(3, 'UTC')), `is_active` AggregateFunction(argMax, UInt8, DateTime64(3, 'UTC'))) AS SELECT toDate(toStartOfMonth(min(s.minute_bucket))) AS session_month, s.video_session_id, anyState(s.user_id) AS user_id, anyState(s.content_id) AS content_id, anyState(s.platform) AS platform, anyState(s.video_resolution) AS video_resolution, anyState(s.country) AS country, anyState(s.app_version) AS app_version, groupUniqArrayMergeState(s.audio_languages) AS audio_languages, groupUniqArrayMergeState(s.subtitle_languages) AS subtitle_languages, anyState(s.player_version) AS player_version, anyMergeState(s.session_start_epoch) AS session_start_epoch, anyMergeState(s.title) AS title, anyMergeState(s.video_type) AS video_type, anyMergeState(s.category) AS category, anyMergeState(s.show_name) AS show_name, argMaxMergeState(s.latest_event_type) AS latest_event_type, argMaxMergeState(s.latest_event) AS latest_event, maxSimpleState(s.last_event_ts) AS last_event_ts, argMaxMergeState(s.is_active) AS is_active FROM silver.session_minute_state AS s GROUP BY s.video_session_id